using System; using System.Collections.Generic; using System.Text.Json; using HitMe.Core;
namespace HitMe.GestureV2 { public sealed class ReplayEvent { public string Kind {get;set;}=""; public int PointerId {get;set;} public float Sx {get;set;} public float Sy {get;set;} public float Gx {get;set;} public float Gy {get;set;} public bool Inside {get;set;} }
 public sealed class ReplayExpected { public bool HasPlaced {get;set;} public bool AimActive {get;set;} public bool Locked {get;set;} public float PositionX {get;set;} public float PositionY {get;set;} public float FacingX {get;set;} public float FacingY {get;set;} }
 public sealed class ReplayFixture { public List<ReplayEvent> Events {get;set;}=new(); public ReplayExpected Expected {get;set;}=new(); }
 public static class GestureReplay { static readonly JsonSerializerOptions Json=new JsonSerializerOptions{PropertyNameCaseInsensitive=true}; public static ReplayFixture Load(string json)=>JsonSerializer.Deserialize<ReplayFixture>(json,Json)??throw new InvalidOperationException("Invalid replay fixture."); public static GestureSnapshot Play(string json,float threshold=10)=>Play(Load(json),threshold); public static GestureSnapshot Play(ReplayFixture fixture,float threshold=10){var g=new PlacementGestureV2();g.BeginRound(Vec2.Zero,PlacementGestureV2.DefaultFacing);foreach(var e in fixture.Events){var s=new Vec2(e.Sx,e.Sy);var p=new Vec2(e.Gx,e.Gy);if(e.Kind=="down")g.PointerDown(e.PointerId,s,p,e.Inside,0);else if(e.Kind=="move")g.PointerMove(e.PointerId,s,p,e.Inside,0,threshold);else if(e.Kind=="up")g.PointerUp(e.PointerId,s,p,e.Inside,0);else if(e.Kind=="lock")g.Lock();}return g.Snapshot();} }
}
